def done_receipt(receipt, check, checkout, run=subprocess.run):
    """(done, reason) for a LANDED receipt: the check command passes in a fresh checkout of the
    landed sha, and npm dependencies are installed from the lockfile before the check runs."""
    if not receipt or receipt.get("state") != "LANDED" or not receipt.get("sha"):
        return False, f"{UNVERIFIED} no LANDED receipt with a sha"
    sha = receipt["sha"]
    check_spec = check or {}
    check_cmd = check_spec.get("check")
    if not check_cmd:
        return False, f"{UNVERIFIED} no check command in receipt"
    git = lambda *a: run(["git", *a], cwd=checkout, capture_output=True, text=True, timeout=300)  # noqa: E731
    if git("fetch", "--quiet", "origin", sha).returncode:
        return False, f"{UNVERIFIED} cannot fetch landed {sha}"
    if git("checkout", "--quiet", "--detach", sha).returncode:
        return False, f"{UNVERIFIED} cannot checkout landed {sha}"
    if (Path(checkout) / "package-lock.json").exists():
        npm = run(["npm", "ci", "--prefer-offline", "--no-audit", "--no-fund"], cwd=checkout, capture_output=True, text=True, timeout=300)
        if npm.returncode:
            return False, f"{UNVERIFIED} npm ci failed for landed {sha}"
    result = run(["sh", "-c", check_cmd], cwd=checkout, capture_output=True, text=True, timeout=300)
    if result.returncode:
        return False, f"{UNVERIFIED} check failed for landed {sha}"
    return True, f"landed {sha} passed check"
